package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamMentalSkillsBank1 {
    private const val T = "මානසික සුවතාව, ජීවන නිපුණතා හා මත්ද්‍රව්‍ය නිවාරණය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ලෝක සෞඛ්‍ය සංවිධානයේ (WHO) නිර්වචනයට අනුව මානසික සෞඛ්‍යය හෙවත් සුවතාව යනු කුමක්ද?", "තමාගේ හැකියාවන් හඳුනාගෙන, එදිනෙදා ජීවිතයේ සාමාන්‍ය ආතතීන්ට සාර්ථකව මුහුණ දෙමින්, ඵලදායීව වැඩ කරමින් සමාජයට දායක විය හැකි යහපැවැත්මේ තත්ත්වයකි", "කිසිදා කේන්ති නොයෑම පමණි", "මානසික රෝහලක නේවාසික නොවීම පමණි", "නිතරම සතුටින් සිනාසෙමින් සිටීම පමණි", "මානසික සුවතාව යනු හුදෙක් මානසික රෝගයක් නොමැතිකම පමණක් නොව පුද්ගල හැකියාවන් සාක්ෂාත් කර ගැනීමේ පූර්ණ සුවපත්භාවයයි."),
        q("මානසිකව නිරෝගී පුද්ගලයෙකු තුළ දැකිය හැකි ප්‍රධානතම සුවිශේෂී ලක්ෂණයක් වන්නේ කුමක්ද?", "ජය පරාජය උපේක්ෂාවෙන් විඳදරා ගනිමින් ගැටලුවලට සාර්ථකව අනුවර්තනය වීමේ හැකියාව (Resilience)", "අන්‍යයන්ගේ අදහස්වලට කිසිසේත් ඇහුම්කන් නොදීම", "තමා සැමවිටම නිවැරදි යැයි සිතීම", "සමාජයෙන් වෙන්ව තනිව ජීවත් වීම", "මානසික නිරෝගීභාවය ඇති තැනැත්තා අභියෝග හා ආතතීන් හමුවේ නොසැලී සමබරව ක්‍රියා කරයි."),
        q("පුද්ගලයෙකු තමාගේ ගුණාංග, සීමාවන්, දක්ෂතා, දුර්වලතා සහ චිත්තවේග පිළිබඳව නිවැරදිව තේරුම් ගැනීම හඳුන්වන්නේ කෙසේද?", "ස්වයං අවබෝධය (Self-awareness)", "ආත්මාර්ථකාමිත්වය", "අහංකාරකම", "සමාජ බිය", "තමා කවුදැයි යථාර්ථවාදීව හඳුනාගැනීම සාර්ථක ජීවිතයකට මුල්වන පළමු ජීවන නිපුණතාවයි."),
        q("තමා වටිනා, ගෞරවනීය සහ ප්‍රයෝජනවත් පුද්ගලයෙකු ලෙස තමා පිළිබඳවම ඇතිකර ගන්නා ධනාත්මක ආත්ම අභිමානය කුමක්ද?", "ස්වයං අභිමානය (Self-esteem)", "ස්වයං රැවටීම", "උඩඟුකම", "ආක්‍රමණශීලී බව", "ඉහළ ස්වයං අභිමානයක් ඇති දරුවන් අභියෝග හමුවේ නොසැලෙන අතර වැරදි පෙළඹවීම්වලට හසු නොවේ."),
        q("අන් අයගේ දුක, වේදනාව හා හැඟීම් තමාගේම දෘෂ්ටිකෝණයෙන් නොව ඔවුන්ගේ පැත්තෙන් තේරුම් ගැනීමේ හැකියාව කුමක්ද?", "සහකම්පනය (Empathy)", "අනුකම්පාව පමණි", "උදාසීනත්වය", "විවේචනය", "අනෙකාගේ සපත්තුවට තම පාදය දමා බැලීම හෙවත් අනුන්ගේ හැඟීම් සංවේදීව වටහා ගැනීම සහකම්පනයයි."),
        q("පුද්ගලයෙකුට තම අරමුණු සාර්ථක කර ගැනීමට හා දක්ෂතා පෙන්වීමට උත්තේජනයක් සපයන ධනාත්මක කෙටිකාලීන ආතතිය කුමක්ද?", "යුස්ට්‍රස් හෙවත් සුභදායී ආතතිය (Eustress)", "ඩිස්ට්‍රස්", "විෂාදය", "භීතිකාව", "විභාගයකට හෝ තරගයකට සූදානම් වීමට අප උනන්දු කරවන හිතකර ආතතිය Eustress වේ."),
        q("පුද්ගලයාගේ කායික හා මානසික සෞඛ්‍ය බිඳ දමමින් එදිනෙදා ක්‍රියාකාරිත්වය අඩපණ කරන අහිතකර දීර්ඝකාලීන ආතතිය කුමක්ද?", "ඩිස්ට්‍රස් හෙවත් පීඩාකාරී ආතතිය (Distress)", "යුස්ට්‍රස්", "සතුට", "උද්යෝගය", "දීර්ඝකාලීන පාලනය කළ නොහැකි ආතතිය ශාරීරික හා මානසික රෝග රැසකට මුල පුරයි."),
        q("හදිසි අනතුරක් හෝ තර්ජනයක් හමුවේ ශරීරය සූදානම් කරවන 'සටන් කිරීම හෝ පලායාම' (Fight or Flight) ප්‍රතිචාරයේදී ස්‍රාවය වන හෝමෝනය කුමක්ද?", "ඇඩ්‍රිනලින් හෝමෝනය (Adrenaline)", "තයිරොක්සින්", "ඉන්සියුලින්", "ඊස්ට්‍රජන්", "අධිවෘක්ක ග්‍රන්ථියෙන් නිපදවන ඇඩ්‍රිනලින් මගින් හෘද ස්පන්දනය වේගවත් කර පේශිවලට රුධිරය සපයයි."),
        q("දීර්ඝකාලීන මානසික ආතතිය නිසා ශරීරයේ අඛණ්ඩව ඉහළ මට්ටමක පවතින ප්‍රතිශක්තිය දුර්වල කරන ආතති හෝමෝනය කුමක්ද?", "කෝටිසෝල් හෝමෝනය (Cortisol)", "ග්ලුකොගන්", "ප්‍රොලැක්ටින්", "මෙලටොනින්", "කෝටිසෝල් මට්ටම දිගු කලක් ඉහළ පැවතීමෙන් මතකය දුර්වල වීම, බඩගින්න අවුල් වීම හා ප්‍රතිශක්තිය හීන වීම සිදුවේ."),
        q("මානසික ආතතියේදී ඇතිවන කායික රෝග ලක්ෂණයක් නොවන්නේ පහත සඳහන් කුමක්ද?", "පෙනීම අසාමාන්‍ය ලෙස දියුණු වීම", "නිතර ඇතිවන හිසරදය සහ කරකැවිල්ල", "හෘද ස්පන්දනය වේගවත් වීම", "නින්ද නොයාම සහ ආහාර අරුචිය", "ආතතියේදී නින්ද නොයාම, ගැස්ට්‍රයිටිස්, පේශි තදවීම ඇති වුවද පෙනීම දියුණු නොවේ."),
        q("මානසික ආතතිය සාර්ථකව කළමනාකරණය කර ගැනීම සඳහා අනුගමනය කළ හැකි විද්‍යාත්මක ලිහිල්කරණ ක්‍රමයක් කුමක්ද?", "ගැඹුරින් හුස්ම ගැනීමේ ව්‍යායාම (Deep Breathing) සහ භාවනාව", "මත්පැන් පානය කිරීම", "ආහාර නොගෙන සිටීම", "දවස පුරා නිදා ගැනීම", "සෙමින් ගැඹුරින් හුස්ම ගැනීම මගින් පරානුකම්පී ස්නායු පද්ධතිය උත්තේජනය වී සිරුර ක්ෂණිකව ලිහිල් වේ."),
        q("පාසල් සිසුන් මුහුණ දෙන අධ්‍යාපනික ආතතිය අවම කර ගැනීම සඳහා අත්‍යවශ්‍ය වන කුසලතාව කුමක්ද?", "ක්‍රමානුකූල කාල කළමනාකරණය (Time Management) සහ වැඩ කල් නොදැමීම", "විභාගයට පෙර දින පමණක් නිදි වැරීම", "පොත් කියවීම අත්හැරීම", "අන් අයගේ පිටපත් ලිවීම", "කාලසටහනකට අනුව එදිනෙදා වැඩ පිළිවෙළකට කිරීමෙන් අනවශ්‍ය විභාග බිය හා පීඩනය පහව යයි."),
        q("ලෝක සෞඛ්‍ය සංවිධානය (WHO) විසින් හඳුන්වා දී ඇති ප්‍රධාන ජීවන නිපුණතා (Core Life Skills) කාණ්ඩ ගණන කීයද?", "මූලික ජීවන නිපුණතා 10කි", "නිපුණතා 5කි", "නිපුණතා 20කි", "නිපුණතා 3කි", "WHO මගින් පුද්ගල පෞරුෂ සංවර්ධනය හා සමාජ අභියෝග ජයගැනීමට මූලික ජීවන නිපුණතා 10ක් ප්‍රකාශයට පත් කර ඇත."),
        q("තොරතුරු හෝ තත්ත්වයක් කිසිදු විමසීමකින් තොරව පිළිනොගෙන, එහි සත්‍ය අසත්‍යතාව සහ යහපත අයහපත තාර්කිකව විමසා බැලීමේ කුසලතාව කුමක්ද?", "විචාරශීලී චින්තනය (Critical Thinking)", "අන්ධ විශ්වාසය", "නිර්මාණශීලී චින්තනය", "කලබලකාරී බව", "වංචනික පෙළඹවීම්, ව්‍යාජ පුවත් සහ මිථ්‍යා මතවලින් මිදීමට විචාරශීලී චින්තනය උපකාරී වේ."),
        q("පවතින ගැටලුවකට සම්ප්‍රදායික රාමුවෙන් බැහැරව නව්‍ය, ඵලදායී හා වෙනස් ආකාරයකින් විසඳුම් සෙවීමේ හැකියාව කුමක්ද?", "නිර්මාණශීලී චින්තනය (Creative Thinking)", "විචාරශීලී චින්තනය", "ස්වයං අවබෝධය", "සහකම්පනය", "නව්‍ය නිර්මාණ බිහිකිරීමට හා අර්බුද නව මුහුණුවරකින් ජයගැනීමට නිර්මාණශීලී චින්තනය මග පාදයි."),
        q("විවිධ විකල්ප සහ ඒවායින් ඇතිවිය හැකි අනාගත ප්‍රතිඵල මැනවින් සලකා බලා වඩාත් සුදුසු විකල්පය තෝරා ගැනීමේ හැකියාව කුමක්ද?", "තීරණ ගැනීමේ නිපුණතාව (Decision Making)", "අහඹු තේරීම", "ගැටලු මගහැරීම", "කල් දැමීම", "හොඳ තීරණයක් මගින් තමාටත් සමාජයටත් යහපතක් අත්වන අතර අවදානම් අවම වේ."),
        q("තමාගේ අයිතිවාසිකම් සහ අවශ්‍යතා අන්‍යයන්ට හානියක් නොවන සේ ඍජුව, අවංකව සහ ගෞරවාන්විතව ප්‍රකාශ කිරීමේ හැසිරීම කුමක්ද?", "තහවුරුශීලී හෙවත් තර්කානුකූල හැසිරීම (Assertive Behavior)", "ආක්‍රමණශීලී හැසිරීම", "යටහත් පහත් හැසිරීම", "පළිගැනීමේ හැසිරීම", "Assertive පුද්ගලයා තමාගේ අයිතිවාසිකම් සුරකින අතරම අනුන්ගේ ගරුත්වයටද හානි නොකරයි."),
        q("අනුන්ගේ අදහස් හා අයිතිවාසිකම් නොසලකා හරිමින්, බලහත්කාරයෙන් හා තර්ජනාත්මකව තමාගේ මතය පැටවීමේ හැසිරීම කුමක්ද?", "ආක්‍රමණශීලී හැසිරීම (Aggressive Behavior)", "තහවුරුශීලී හැසිරීම", "යටහත් පහත් හැසිරීම", "සාමකාමී හැසිරීම", "ආක්‍රමණශීලී හැසිරීම ගැටුම් සහ සබඳතා බිඳවැටීමට මූලික හේතුවකි."),
        q("තමාගේ අයිතිවාසිකම් පාවා දෙමින්, අනුන්ගේ අසාධාරණ ඉල්ලීම්වලට බියෙන් හෝ ලැජ්ජාවෙන් එකඟ වන දුර්වල හැසිරීම කුමක්ද?", "යටහත් පහත් හෙවත් අක්‍රීය හැසිරීම (Passive Behavior)", "තහවුරුශීලී හැසිරීම", "ආක්‍රමණශීලී හැසිරීම", "නායකත්ව හැසිරීම", "Passive පුද්ගලයා අන්‍යයන් සතුටු කිරීමට ගොස් තමා අනතුරේ හෙළා ගනී."),
        q("මිතුරන් දුම්පානයට හෝ මත්ද්‍රව්‍ය ගැනීමට බලකරන විට තහවුරුශීලී පුද්ගලයෙකු ප්‍රතිචාර දැක්විය යුතු නිවැරදි ආකාරය කුමක්ද?", "ඍජුව ඇස් දෙස බලා 'නැහැ, මම කිසිසේත්ම මත්ද්‍රව්‍ය ගන්නේ නැහැ' යැයි ස්ථිරව හා සන්සුන්ව ප්‍රකාශ කිරීම", "බියෙන් බිම බලාගෙන සිටීම", "මිතුරන් සතුටු කිරීමට එක් උගුරක් බීම", "කෑගසා රණ්ඩු වීම", "පැහැදිලිව හා නොපැකිලිව 'එපා' කියා එම අනතුරුදායක ස්ථානයෙන් ඉවත් වීම හොඳම පියවරයි."),
        q("සන්නිවේදනයේදී කථා කරන්නාගේ වචනවලට මෙන්ම ඔහුගේ ශාරීරික ඉරියව්වලටද පූර්ණ අවධානය යොමු කරමින් සවන් දීම හඳුන්වන්නේ කෙසේද?", "ක්‍රියාකාරී සවන්දීම (Active Listening)", "උදාසීන සවන්දීම", "මවාපෑම", "බාධා කිරීම", "ක්‍රියාකාරී සවන්දීම සාර්ථක අන්තර්-පුද්ගල සබඳතාවල රහසයි."),
        q("දුම්කොළ (Tobacco) නිෂ්පාදනවල අඩංගු වන මොළයේ ඩෝපමයින් මුදාහැර දැඩි ලෙස ඇබ්බැහි කරවන ප්‍රධාන රසායනික ද්‍රව්‍යය කුමක්ද?", "නිකොටින් (Nicotine)", "තාර", "කාබන් මොනොක්සයිඩ්", "ඊතයිල් මධ්‍යසාරය", "නිකොටින් ක්ෂණිකව රුධිරයට උරාගෙන මොළයට බලපෑම් කර ප්‍රබල කායික හා මානසික ඇබ්බැහියක් ඇති කරයි."),
        q("දුම්වැටි දුමාරයේ අඩංගු පෙනහලුවල ඇලී පිළිකා (Carcinogens) ඇති කරන දුඹුරු පැහැති දුස්ස්‍රාවී රසායනික මිශ්‍රණය කුමක්ද?", "තාර (Tar)", "නිකොටින්", "ජලය", "කාබන් ඩයොක්සයිඩ්", "තාර පෙනහලුවල වායු කෝෂ සහ පක්ෂ්ම විනාශ කර පෙනහලු පිළිකා හා එම්ෆයිසීමා රෝගය සාදයි."),
        q("දුම්වැටි දුමේ අඩංගු වන, රුධිරයේ හිමොග්ලොබින් සමග බැඳී ඔක්සිජන් ප්‍රවාහන ධාරිතාව දැඩි ලෙස පහත හෙළන විෂ වායුව කුමක්ද?", "කාබන් මොනොක්සයිඩ් (Carbon Monoxide — CO)", "නයිට්‍රජන්", "ඔක්සිජන්", "හීලියම්", "කාබන් මොනොක්සයිඩ් හිමොග්ලොබින් සමග බැඳීම නිසා හෘදයට හා මොළයට ඔක්සිජන් හිඟ වී හෘදයාබාධ ඇතිවේ."),
        q("තමා දුම් නොබොන නමුත් අන් අය බොන දුම්වැටි දුම ආඝ්‍රාණය කිරීමෙන් රෝගී වීම හඳුන්වන්නේ කෙසේද?", "අක්‍රීය දුම්පානය හෙවත් ද්විතියික දුම්පානය (Passive / Second-hand Smoking)", "සක්‍රීය දුම්පානය", "හුමාලය ඇල්ලීම", "පිරිසිදු වාතය ගැනීම", "අක්‍රීය දුම්පානය නිසා දරුවන්ට ඇදුම, නියුමෝනියාව සහ වැඩිහිටියන්ට හෘද රෝග බහුලව වැළඳේ."),
        q("මත්පැන්වල (Alcohol) අඩංගු වන මධ්‍යම ස්නායු පද්ධතිය මර්දනය කරන (CNS Depressant) ප්‍රධාන රසායනික සංඝටකය කුමක්ද?", "ඊතයිල් මධ්‍යසාරය හෙවත් එතනෝල් (Ethyl Alcohol / Ethanol)", "මීතයිල් මධ්‍යසාරය", "ග්ලිසරෝල්", "ඇසිටෝන්", "එතනෝල් මොළයේ ක්‍රියාකාරිත්වය මන්දගාමී කර ප්‍රතික්‍රියා කාලය ප්‍රමාද කරයි."),
        q("මත්පැන් පානය කිරීමෙන් පසු පුද්ගලයෙකුගේ ප්‍රතික්‍රියා කාලය (Reaction Time) ප්‍රමාද වීම නිසා සිදුවන ප්‍රධාන අනතුර කුමක්ද?", "මාරාන්තික රිය අනතුරු (Road Traffic Accidents) සිදුවීම", "පොත් කියවීමට නොහැකි වීම", "කුසගින්න වැඩිවීම", "කතා බහ අඩුවීම", "තිරිංග යෙදීමේ හා තීරණ ගැනීමේ කාලය ප්‍රමාද වීම නිසා බීමත් රියදුරන් දරුණු අනතුරු සිදුකරයි."),
        q("දීර්ඝකාලීනව අධික ලෙස මත්පැන් පානය කිරීම නිසා අක්මා සෛල විනාශ වී තන්තුමය පටක සෑදී අක්මාව හැකිළී යාමේ රෝගය කුමක්ද?", "අක්මා සිරෝසිස් (Liver Cirrhosis)", "අක්මා ක්ෂය රෝගය", "අක්මා ගැස්ට්‍රයිටිස්", "අක්මා මැලේරියාව", "සිරෝසිස් යනු ආපසු හැරවිය නොහැකි අක්මා අකර්මණ්‍යතාවයක් වන අතර අවසානයේ මරණය ගෙනදෙයි."),
        q("මත්පැන් ශරීරයට ඇතුළු වූ විට එය ප්‍රධාන වශයෙන්ම පරිවෘත්තීය කර විෂහරණය කරනු ලබන ඉන්ද්‍රිය කුමක්ද?", "අක්මාව (Liver)", "පෙනහලු", "හෘදය", "වකුගඩු පමණි", "සිරුරට ඇතුළු වන මධ්‍යසාරවලින් 90%කට වඩා විෂහරණය කරන්නේ අක්මාව මගිනි."),
        q("ගංජා (Cannabis / Marijuana) ශාකයේ අඩංගු වන මනෝභ්‍රාන්ති (Hallucinations) සහ මතක දුර්වලතා ඇති කරන ප්‍රධාන මනෝක්‍රියාකාරී ද්‍රව්‍යය කුමක්ද?", "ටෙට්‍රාහයිඩ්‍රොකැනබිනෝල් (THC)", "නිකොටින්", "කැෆේන්", "මෝෆීන්", "THC මොළයේ ප්‍රතිග්‍රාහක සමග බැඳී විඥානය අවුල් කර මනෝභ්‍රාන්ති ජනනය කරයි."),
        q("අබිං (Opium) ශාකයෙන් නිස්සාරණය කර රසායනිකව සකසන අතිශය විනාශකාරී ඇබ්බැහිවීමක් සහිත නිද්‍රාකාරී මත්ද්‍රව්‍යය කුමක්ද?", "හෙරොයින් (Heroin)", "මරිජුවානා", "ඇස්ප්‍රින්", "කෝලා", "හෙරොයින් ස්නායු පද්ධතියට දැඩිව ඇබ්බැහි කරවන අතර අධික මාත්‍රාවකින් ශ්වසනය අඩපණ වී ක්ෂණික මරණය ගෙනදෙයි."),
        q("නූතන තරුණ පරපුර අතර පැතිර යන 'අයිස්' (ICE) නමින් හඳුන්වන ඉතා කෙටි කලකින් මොළය විනාශ කරන කෘත්‍රිම උත්තේජක මත්ද්‍රව්‍යය කුමක්ද?", "මෙතැම්ෆෙටමින් (Crystal Methamphetamine)", "පැරසිටමෝල්", "පෙනිසිලින්", "ඊතර්", "අයිස් මගින් මොළයේ සෛල විනාශ වී දැඩි ප්‍රචණ්ඩත්වය, නින්ද නොයාම සහ මානසික විකෘතිතා හටගනී."),
        q("මත්ද්‍රව්‍යවලට ඇබ්බැහි වූ අයෙකුට එම ද්‍රව්‍ය නොමැති වූ විට ඇතිවන දැඩි වෙව්ලීම, වේදනාව, දහඩිය දැමීම සහ නොසන්සුන් බව හඳුන්වන්නේ කෙසේද?", "ඉවත් වීමේ රෝග ලක්ෂණ (Withdrawal Symptoms)", "සුවපත් වීමේ සලකුණු", "ප්‍රතිශක්තිය වැඩිවීම", "නිරෝගී ලක්ෂණ", "ශරීරය මත්ද්‍රව්‍ය මත රඳා පවතින බැවින් එය නතර කළ විට දරුණු කායික වේදනා හටගනී."),
        q("ශ්‍රී ලංකාවේ දුම්කොළ හා මද්‍යසාර පිළිබඳ ජාතික අධිකාරී (NATA) පනත සම්මත වූයේ කුමන වසරේද?", "2006 වසරේදී (2006 අංක 27 දරන පනත)", "1990 වසරේදී", "2015 වසරේදී", "2020 වසරේදී", "NATA පනත මගින් ශ්‍රී ලංකාවේ දුම්කොළ හා මත්පැන් පාලනයට සුවිශේෂී නීතිමය බලතල ලබා දී ඇත."),
        q("NATA පනතට අනුව දුම්කොළ නිෂ්පාදන හෝ මත්පැන් අලෙවි කිරීම සපුරා තහනම් කර ඇති වයස් සීමාව කුමක්ද?", "වයස අවුරුදු 21ට අඩු පුද්ගලයන්ට", "වයස අවුරුදු 18ට අඩු අයට පමණි", "වයස අවුරුදු 16ට අඩු අයට", "වයස අවුරුදු 12ට අඩු අයට", "ශ්‍රී ලංකා නීතිය අනුව අවුරුදු 21ට අඩු කිසිවෙකුට දුම්කොළ හෝ මත්පැන් විකිණීම හෝ ඔවුන් ලවා විකිණවීම දඬුවම් ලැබිය හැකි වරදකි."),
        q("NATA පනත මගින් දුම්වැටි අලෙවිය සම්බන්ධයෙන් පනවා ඇති වැදගත්ම සීමාකාරී නීතියක් වන්නේ කුමක්ද?", "සිල්ලරට තනි දුම්වැටි (Single Cigarettes) අලෙවි කිරීම සපුරා තහනම් කිරීම", "දුම්වැටි මිල අඩු කිරීම", "නොමිලේ දුම්වැටි බෙදා හැරීම", "ඕනෑම තැනක විකිණීමට ඉඩ දීම", "පාසල් ළමුන් හා තරුණයන් පහසුවෙන් මිලදී ගැනීම වැළැක්වීමට තනි දුම්වැටි අලෙවිය තහනම් කර ඇත."),
        q("ශ්‍රී ලංකාවේ දුම්වැටි පැකට්ටුවක මතුපිටින් අවම වශයෙන් කොපමණ ප්‍රතිශතයක රූපමය සෞඛ්‍ය අවවාද (Pictorial Health Warnings) මුද්‍රණය කළ යුතුද?", "පැකට්ටුවේ මතුපිටින් 80%ක ප්‍රමාණයක", "20%ක", "50%ක", "10%ක", "දුම්පානයේ බිහිසුණු පිළිකා රෝග පිළිබඳ ඡායාරූප පැකට්ටුවේ 80%ක ප්‍රමාණයක මුද්‍රණය කිරීම අනිවාර්ය කර ඇත."),
        q("ශ්‍රී ලංකාවේ පොදු ස්ථානවල (පාසල්, රෝහල්, පොදු ප්‍රවාහන සේවා, රාජ්‍ය ආයතන) දුම්පානය කිරීම සම්බන්ධයෙන් නීතිය කුමක්ද?", "සපුරා තහනම් වන අතර එය රුපියල් දහස් ගණනක දඩයකට යටත් වන වරදකි", "ඕනෑම කෙනෙකුට නිදහසේ කළ හැක", "අවසර පත්‍රයක් සහිතව කළ හැක", "රාත්‍රී කාලයේදී පමණක් කළ හැක", "පොදු ස්ථානවල අක්‍රීය දුම්පානයෙන් මහජනතාව ආරක්ෂා කිරීමට ප්‍රසිද්ධියේ දුම්බීම නීතියෙන් තහනම්ය."),
        q("ශ්‍රී ලංකාවේ රූපවාහිනී, ගුවන්විදුලි, පුවත්පත් හෝ පුවරු මගින් දුම්වැටි හා මත්පැන් ප්‍රචාරණය කිරීම (Advertisements & Sponsorships) සම්බන්ධ නීතිය කුමක්ද?", "සම්පූර්ණයෙන්ම සපුරා තහනම් කර ඇත", "රාත්‍රී 10න් පසු විකාශය කළ හැක", "ක්‍රීඩා තරගවලදී පමණක් කළ හැක", "අසීමිතව ප්‍රචාරය කළ හැක", "කිසිදු සෘජු හෝ වක්‍ර ප්‍රචාරණයක් හෝ අනුග්‍රාහකත්වයක් ලබාදීම NATA පනතින් තහනම් කර ඇත."),
        q("ශ්‍රී ලංකාවේ අන්තරායකර ඖෂධ පාලක ජාතික මණ්ඩලයේ (NDDCB) මත්ද්‍රව්‍ය නිවාරණ සහ උපදේශන ක්ෂණික ඇමතුම් අංකය කුමක්ද?", "1984", "119", "1990", "1929", "1984 අංකය මගින් මත්ද්‍රව්‍යවලට ඇබ්බැහි වූවන් පුනරුත්ථාපනයට සහ උපදේශනයට ක්ෂණික සහය ලැබේ."),
        q("මත්ද්‍රව්‍ය භාවිතයෙන් තොරව ජීවිතයේ ගැටලුවලට මුහුණ දීමේ හැකියාව වර්ධනය කර ගැනීමට ඇති හොඳම ආරක්ෂක පවුර කුමක්ද?", "පවුලේ සුහදශීලී සබඳතා, යහපත් මිතුරු ඇසුර සහ ජීවන නිපුණතා ප්‍රගුණ කිරීම", "තනිව හුදකලා වීම", "අන්තර්ජාලයට ඇබ්බැහි වීම", "සැකයෙන් ජීවත් වීම", "ශක්තිමත් පවුල් පසුබිමක් හා ජීවන නිපුණතා ඇති දරුවන් කිසිවිටෙකත් මත්ද්‍රව්‍ය උගුල්වලට හසු නොවේ."),
        q("මත්ද්‍රව්‍යවලට ඇබ්බැහි වූ පුද්ගලයෙකු අපරාධකරුවෙකු ලෙස නොව රෝගියෙකු ලෙස සලකා ප්‍රතිකාර කළ යුත්තේ මන්ද?", "ඇබ්බැහිවීම යනු මොළයේ ක්‍රියාකාරිත්වය වෙනස් වන නිදන්ගත රෝගී තත්ත්වයක් බැවින් නිසි වෛද්‍ය හා මනෝවිද්‍යාත්මක ප්‍රතිකාරවලින් සුවපත් කළ හැකි නිසා", "ඔවුන්ට දඬුවම් කිරීමට බිය නිසා", "මත්ද්‍රව්‍ය හොඳ දෙයක් නිසා", "කිසිදු හේතුවක් නැත", "මත්ද්‍රව්‍යවලට ගොදුරු වූවන් නිසි පුනරුත්ථාපනය (Rehabilitation) මගින් නැවත සාමාන්‍ය සමාජයට එක් කළ හැක."),
        q("යහපත් මිත්‍රත්වයක (Positive Peer Relationship) තිබිය යුතු ප්‍රධාන ගුණාංගය කුමක්ද?", "එකිනෙකාගේ දියුණුවට සහ අධ්‍යාපනයට උදව් කරමින් වැරදි පෙළඹවීම්වලින් වළක්වා ගැනීම", "නිතර නීති විරෝධී දේවලට පෙළඹවීම", "රහස්‍ය වැරදි සැඟවීම", "මුදල් නාස්ති කිරීමට පෙළඹවීම", "නამდසු මිතුරා සැමවිටම යහපතෙහි යොදවයි. අයහපතෙන් වළක්වයි."),
        q("විෂාදය (Depression) නම් මානසික රෝගී තත්ත්වය හඳුනාගත හැකි ප්‍රධාන රෝග ලක්ෂණයක් වන්නේ කුමක්ද?", "සති දෙකකට වඩා අඛණ්ඩව පවතින දැඩි දුක, කලකිරීම, කිසිදු දෙයකින් සතුටක් නොලැබීම සහ සියදිවි නසාගැනීමේ සිතුවිලි", "දිනක සුළු කේන්තියක් පමණක් ඇතිවීම", "අධික ලෙස ක්‍රීඩා කිරීම", "පොත් කියවීමට ප්‍රිය කිරීම", "විෂාදය යනු සරල දුකක් නොව වහාම මනෝ වෛද්‍ය ප්‍රතිකාර අවශ්‍ය වන රෝගී තත්ත්වයකි."),
        q("ශ්‍රී ලංකාවේ මානසික ගැටලු හා සියදිවි නසාගැනීම් වැළැක්වීම සඳහා පැය 24 පුරා ක්‍රියාත්මක වන ජාතික උපකාරක දුරකථන අංකය කුමක්ද?", "1926 (ජාතික මානසික සෞඛ්‍ය විද්‍යායතනය — NIMH)", "119", "1990", "110", "1926 ක්ෂණික අංකය හරහා නොමිලේ හා රහස්‍යභාවය සුරකිමින් මනෝ වෛද්‍ය උපදේශන සහය ලැබේ."),
        q("සුමිත්‍රයෝ (Sumithrayo) සංවිධානය මගින් ශ්‍රී ලංකාවේ ලබාදෙන ප්‍රධාන සමාජ සේවාව කුමක්ද?", "චිත්තවේගීය පීඩාවලින් පෙළෙන අයට සහ සියදිවි නසාගැනීමේ සිතුවිලි ඇති අයට නොමිලේ රහසිගත චිත්තවේගීය සහය ලබාදීම", "මුදල් ණය දීම", "ක්‍රීඩා පුහුණුව", "රැකියා සැපයීම", "සුමිත්‍රයෝ ස්වේච්ඡා සංවිධානය දශක ගණනාවක් පුරා මානසික පීඩාවලින් පෙළෙන්නන්ට සවන් දෙමින් ජීවිත බේරා ගනී."),
        q("නව යොවුන් වියේදී ඇතිවන ආතතිය සමනය කර ගැනීමට ක්‍රීඩාව (Sports) ඉවහල් වන්නේ කෙසේද?", "ශාරීරික ක්‍රියාකාරකම්වලදී මොළයෙන් සතුට දනවන එන්ඩොෆින් (Endorphins) හෝමෝන ස්‍රාවය වී මනස ප්‍රබෝධමත් වන බැවින්", "ක්‍රීඩාවෙන් කේන්තිය වැඩිවන නිසා", "වෙහෙස වී නිදා ගැනීමට පමණක්", "අන් අයට පහර දීමට හැකි නිසා", "ක්‍රීඩාවේ යෙදෙන විට මොළයේ එන්ඩොෆින් රසායන නිදහස් වී ස්වභාවිකව ආතතිය පහව යයි."),
        q("පාසල් සිසුවෙකු තමාගේ මානසික ගැටලුවක් විසඳා ගැනීමට මුලින්ම උපදෙස් පැතිය යුතු පාසලේ සිටින නිලධාරියා කවුරුන්ද?", "පාසල් මාර්ගෝපදේශන හා උපදේශන භාර ගුරුභවතුන් (School Guidance Counselor)", "පාසල් මුරකරු", "ආපනශාලා සේවකයා", "නොදන්නා බාහිර පුද්ගලයන්", "පාසල් උපදේශක ගුරුවරුන් රහස්‍යභාවය සුරකිමින් සිසුන්ගේ ගැටලුවලට මගපෙන්වීම සිදුකරයි."),
        q("දුම්වැටි වෙනුවට භාවිත කරන ඊ-සිගරට් හෙවත් වේප් (E-cigarettes / Vaping) භාවිතය පිළිබඳ නිවැරදි විද්‍යාත්මක සත්‍යය කුමක්ද?", "වේප් කිරීමද නිකොටින් සහ විෂ රසායනික සහිත පෙණහලු විනාශ කරන හානිකර ඇබ්බැහි වීමකි", "එය 100%ක්ම නිරෝගී වාෂ්පයකි", "එයින් පෙනහලු පිරිසිදු වේ", "එහි කිසිදු විෂක් නැත", "වේප් දුමෙහි අඩංගු රසායනික මගින් EVALI නම් දරුණු පෙනහලු ආබාධ සහ හෘද රෝග ඇතිවේ."),
        q("මත්ද්‍රව්‍ය නිවාරණය පිළිබඳ සමාජය දැනුවත් කිරීමේදී පාසල් දරුවන්ට ඉටුකළ හැකි වැදගත්ම කාර්යභාරය කුමක්ද?", "තමා මත්ද්‍රව්‍යවලින් සම්පූර්ණයෙන්ම වැළකී සිටිමින් තම මිතුරන් හා පවුලේ සාමාජිකයන් දැනුවත් කිරීම", "මත්ද්‍රව්‍ය විකිණීම", "මත්ද්‍රව්‍ය ගන්නා අය සමග රණ්ඩු වීම", "කිසිදු ක්‍රියාවක් නොකර සිටීම", "පාසල් දරුවන්ගේ ආදර්ශමත් හැසිරීම හා දැනුවත් කිරීම සමාජ පරිවර්තනයකට ප්‍රබල බලවේගයකි."),
        q("පුද්ගලයෙකුගේ මානසික පීඩනය සහ කෝපය පාලනය කර ගැනීම සඳහා WHO මගින් නිර්දේශිත මූලික ජීවන නිපුණතාව කුමක්ද?", "චිත්තවේගවලට මුහුණ දීම (Coping with Emotions)", "නිර්මාණශීලී චින්තනය", "තීරණ ගැනීම", "ඵලදායී සන්නිවේදනය", "තමා තුළ සහ අන්‍යයන් තුළ ඇතිවන කෝපය, දුක හා බිය වැනි හැඟීම් හඳුනාගෙන ඒවාට සුදුසු ලෙස ප්‍රතිචාර දැක්වීම මෙයට අයත් වේ."),
        q("එදිනෙදා ජීවිතයේදී ඇතිවන පීඩාකාරී තත්ත්වයන් හඳුනාගෙන ඒවායින් මිදීමට කටයුතු කිරීම හඳුන්වන ජීවන නිපුණතාව කුමක්ද?", "මානසික ආතතියට මුහුණ දීම (Coping with Stress)", "සහකම්පනය", "විචාරශීලී චින්තනය", "ස්වයං අවබෝධය", "ආතතිය ඇති කරන හේතු හඳුනාගෙන විවේකය, ව්‍යායාම හා ජීවන රටා වෙනස්කම් තුළින් ආතතිය පාලනය කිරීම මෙයයි."),
        q("තමාගේ අදහස් පැහැදිලිව අන් අයට ඉදිරිපත් කිරීමටත් අන් අයගේ අදහස්වලට සවන් දීමටත් උපකාරී වන නිපුණතාව කුමක්ද?", "ඵලදායී සන්නිවේදනය (Effective Communication)", "නිර්මාණශීලී චින්තනය", "ගැටලු විසඳීම", "ආතතියට මුහුණ දීම", "වාචික හා නිර්වාචික (Body language) ක්‍රම ඔස්සේ සුහදව හා පැහැදිලිව අදහස් හුවමාරු කිරීම මෙයට ඇතුළත් වේ."),
        q("පවුලේ සාමාජිකයන්, මිතුරන් සහ ගුරුවරුන් සමග සුහදශීලී හා ගෞරවනීය සබඳතා පවත්වා ගැනීමේ කුසලතාව කුමක්ද?", "අන්තර්-පුද්ගල සබඳතා නිපුණතාව (Interpersonal Relationship Skills)", "ස්වයං අවබෝධය", "තීරණ ගැනීම", "ගැටලු විසඳීම", "යහපත් අන්තර් පුද්ගල සබඳතා පවත්වා ගැනීම පුද්ගලයාගේ මානසික සුවතාවයට ඍජුවම දායක වේ."),
        q("ජීවිතයේ මුහුණ දෙන සංකීර්ණ අභියෝග පියවරෙන් පියවර විශ්ලේෂණය කර සුදුසු පිළියම් සෙවීමේ ජීවන නිපුණතාව කුමක්ද?", "ගැටලු විසඳීමේ නිපුණතාව (Problem Solving)", "සහකම්පනය", "චිත්තවේග පාලනය", "අන්තර්-පුද්ගල සබඳතා", "ගැටලුව හඳුනාගෙන විකල්ප විසඳුම් සොයා වඩාත් ඵලදායී විසඳුම ක්‍රියාවට නැංවීම මෙමගින් සිදුවේ."),
        q("ගැටලු විසඳීමේ ක්‍රියාවලියේදී ගත යුතු නිවැරදි පළමු පියවර කුමක්ද?", "ගැටලුව හා එයට මුල් වූ සැබෑ හේතුව නිවැරදිව හඳුනාගැනීම", "වහාම අනුන්ට දොස් පැවරීම", "ගැටලුවෙන් පලා යාම", "අහඹු තීරණයක් ගැනීම", "සැබෑ ගැටලුව කුමක්දැයි පැහැදිලිව වටහා ගැනීමෙන් තොරව නිවැරදි විසඳුමකට ළඟා විය නොහැක."),
        q("අන්තර්ජාලය, ස්මාර්ට් ජංගම දුරකථන හා වීඩියෝ ක්‍රීඩා පාලනයකින් තොරව භාවිත කිරීම නිසා සිසුන් තුළ ඇතිවන මානසික ගැටලුව කුමක්ද?", "ඩිජිටල් ඇබ්බැහිවීම සහ සමාජ හුදකලාව (Digital Addiction & Social Isolation)", "මානසික ඒකාග්‍රතාව වැඩිවීම", "ශාරීරික යෝග්‍යතාව ඉහළ යාම", "නින්දේ ගුණාත්මකභාවය වැඩිවීම", "අධික තිර කාලය (Screen time) නිසා නින්ද අඩුවීම, ඇස් වෙහෙස සහ පවුල් සබඳතා දුර්වල වීම හටගනී."),
        q("සමාජ මාධ්‍ය ඔස්සේ තවත් පුද්ගලයෙකුට අපහාස කිරීම, තර්ජනය කිරීම හෝ මානසික පීඩා එල්ල කිරීම හඳුන්වන්නේ කෙසේද?", "සයිබර් හිරිහැර කිරීම (Cyberbullying)", "ඵලදායී සන්නිවේදනය", "මිත්‍රශීලී ඇසුර", "ඩිජිටල් සාක්ෂරතාව", "සයිබර් හිරිහැර නිසා යොවුන් දරුවන් තුළ දැඩි කාංසාව, විෂාදය සහ ආත්ම විශ්වාසය බිඳවැටීම සිදුවේ."),
        q("සයිබර් හිරිහැර කිරීමකට (Cyberbullying) ලක් වූ පාසල් සිසුවෙකු ගත යුතු බුද්ධිමත්ම පියවර කුමක්ද?", "ප්‍රතිචාර දැක්වීමෙන් වැළකී, සාක්ෂි (Screenshots) සුරැකිව තබාගෙන දෙමාපියන් හෝ ගුරුවරුන් දැනුවත් කිරීම", "ඔවුන්ට පෙරළා බැණ වැදීම", "පාසල් යාම නතර කිරීම", "කිසිවෙකුට නොකියා දුක් වීම", "සාක්ෂි රැස්කර විශ්වාසවන්ත වැඩිහිටියන්ගේ හා නීතියේ පිහිට පැතීම ආරක්ෂිතම විසඳුමයි."),
        q("තම ශක්තීන් හා දුර්වලතා හඳුනාගෙන අවස්ථා හා තර්ජන විශ්ලේෂණය කිරීමට යොදා ගන්නා කළමනාකරණ මෙවලම කුමක්ද?", "SWOT විශ්ලේෂණය", "BMI දර්ශකය", "DRABC ක්‍රමය", "RICE ක්‍රමය", "Strengths, Weaknesses, Opportunities, Threats යන අංග 4 පරීක්ෂා කිරීමෙන් පුද්ගල සංවර්ධනය පහසු වේ."),
        q("අසාමාන්‍ය ලෙස නිතර ඇතිවන අසාධාරණ බිය, නොසන්සුන් බව සහ අධික හෘද ස්පන්දනය ලක්ෂණ ලෙස පෙන්වන මානසික තත්ත්වය කුමක්ද?", "කාංසා ආබාධය (Anxiety Disorder)", "සුභදායී ආතතිය", "උද්යෝගය", "ආත්ම විශ්වාසය", "සාමාන්‍ය බිය ඉක්මවා දෛනික කටයුතුවලට බාධා වන පරිදි පවතින කලබලකාරී මානසික තත්ත්වය කාංසාවයි."),
        q("සෑම දෙයක් දෙසම සැකයෙන් හා අසුභවාදීව බැලීම වෙනුවට අභියෝග තුළින් අවස්ථා දැකීමේ මානසික පුරුද්ද කුමක්ද?", "ධනාත්මක චින්තනය (Positive Thinking)", "අශුභවාදය", "මානසික කම්පනය", "අධික භීතිය", "ධනාත්මක චින්තනය මගින් පීඩාකාරී අවස්ථාවලදී පවා බලාපොරොත්තු සහගතව ඉදිරියට යාමට ශක්තිය සපයයි."),
        q("මානසික සුවතාවය සඳහා ප්‍රමාණවත් රාත්‍රී නින්දක් ලැබීම අත්‍යවශ්‍ය වන්නේ මන්ද?", "නින්දේදී මොළයේ ස්නායු සෛල විවේක ගෙන මතකය තහවුරු වීම සහ හැඟීම් සමබර වීම සිදුවන බැවින්", "ශරීරයේ බර වැඩි කර ගැනීමට පමණක්", "කාලය නාස්ති කිරීමට", "ආහාර දිරවීම නතර කිරීමට", "නව යොවුන් වියේ දරුවෙකුට දිනකට පැය 8-9ක සුව නින්දක් මානසික ප්‍රබෝධය සඳහා අත්‍යවශ්‍ය වේ."),
        q("සුවබර රාත්‍රී නින්දක් (Sleep Hygiene) ලබාගැනීමට නින්දට පෙර අනුගමනය කළ යුතු යහපත් පුරුද්ද කුමක්ද?", "නින්දට පැයකට පෙර ජංගම දුරකථන හා රූපවාහිනී තිර භාවිතය නතර කර සැහැල්ලු වීම", "තද කෝපි පානය කිරීම", "රාත්‍රී මධ්‍යම රාත්‍රියේ දැඩි ව්‍යායාම කිරීම", "භයානක චිත්‍රපට නැරඹීම", "නිල් ආලෝකය මගින් නින්ද ඇති කරන මෙලටොනින් හෝමෝනය අඩපණ කරන බැවින් නින්දට පෙර තිර භාවිතය අවම කළ යුතුය."),
        q("පුද්ගලයෙකුගේ මානසික ආතතිය හා රුධිර පීඩනය අඩු කර ගැනීමට ඉතාමත් ඵලදායී සරල ආධ්‍යාත්මික හා මානසික පුහුණුව කුමක්ද?", "සතිමත්භාවය හෙවත් ආනාපානසති භාවනාව (Mindfulness Meditation)", "අධික ශබ්දයෙන් ගීත ඇසීම", "අනුන් සමග වාද කිරීම", "නිරාහාරව සිටීම", "වර්තමාන මොහොත කෙරෙහි සිහි නුවණින් අවධානය යොමු කිරීම මගින් මනසේ සංසුන් බව ඉහළ යයි."),
        q("පාසල් පරිසරයේ සිසුන් අතර ගැටුම් සාමකාමීව නිරාකරණය කර ගැනීමට යොදාගත යුතු හොඳම ක්‍රමය කුමක්ද?", "සාකච්ඡා කිරීම, අනෙකාගේ මතයට සවන් දීම සහ සමථකරණය (Negotiation & Mediation)", "ශාරීරිකව පහර දීම", "දෙපිරිස කතා නොකර සිටීම", "අවමන් කිරීම", "දෙපාර්ශවයටම ජයග්‍රහණයක් ලැබෙන (Win-win) සාමකාමී සාකච්ඡා මගින් ගැටුම් විසඳාගත යුතුය."),
        q("මත්පැන් පානය කරන අයෙකුගේ ගමනේ සමබරතාවය බිඳ වැටී වැනි වැනී ඇවිදීමට හේතුව මොළයේ කුමන කොටසට ඇල්කොහොල් බලපෑම නිසාද?", "අනුමස්තිෂ්කය (Cerebellum)", "සුෂුම්නා ශීර්ෂකය", "හයිපොතැලමසය", "පිටියුටරිය", "චලන සමායෝජනය හා සමබරතාවය පාලනය කරන අනුමස්තිෂ්කයේ ක්‍රියාකාරිත්වය මත්පැන් මගින් අඩපණ කෙරේ."),
        q("මත්පැන් අධික මාත්‍රාවක් ගැනීම නිසා මොළයේ අත්‍යවශ්‍ය මධ්‍යස්ථාන අකර්මණ්‍ය වී හුස්ම ගැනීම පවා නතර විය හැක්කේ කුමන කොටස අඩපණ වීමෙන්ද?", "සුෂුම්නා ශීර්ෂකය (Medulla Oblongata)", "අනුමස්තිෂ්කය", "තැලමසය", "මස්තිෂ්ක බාහිකය", "ශ්වසනය හා හෘද ස්පන්දනය පාලනය කරන සුෂුම්නා ශීර්ෂකය අධික මත්පැන් නිසා අඩපණ වීම මාරාන්තික වේ."),
        q("බුලත් විට සැපීම හා පුවක් භාවිතය මගින් ප්‍රධාන වශයෙන්ම හටගන්නා පිළිකා වර්ගය කුමක්ද?", "මුඛ පිළිකා (Oral Cancer)", "පෙනහලු පිළිකා", "අස්ථි පිළිකා", "වකුගඩු පිළිකා", "දුම්කොළ, හුණු සහ පුවක්වල අඩංගු ඇරෙකොලින් රසායනිකය මගින් මුඛයේ ශ්ලේෂ්මල පටලය විකෘති වී මුඛ පිළිකා සාදයි."),
        q("මුඛ පිළිකාවක පූර්ව අවධියේදී මුඛය ඇතුළත දැකිය හැකි ප්‍රධාන අවවාදාත්මක ලක්ෂණයක් වන්නේ කුමක්ද?", "කම්මුල් ඇතුළත සුදු හෝ රතු ලප ඇතිවීම සහ මුඛය විවෘත කිරීමට අපහසු වීම (OSMF)", "දත් සුදු පැහැ වීම", "කෙළ වැඩිවීම", "හිසරදය", "මුඛයේ සුදු ලප (Leukoplakia) හෝ ශ්ලේෂ්මල තදවීම මුඛ පිළිකා පූර්ව අවදානම් සලකුණු වේ."),
        q("නව යොවුන් වියේ තරුණයන් දුම්පානයට හා මත්පැන්වලට යොමු කිරීම සඳහා වෙළඳ සමාගම් යොදාගන්නා සූක්ෂ්ම වක්‍ර උපක්‍රමයක් වන්නේ කුමක්ද?", "චිත්‍රපට, සමාජ මාධ්‍ය සහ ක්‍රීඩා තරු හරහා එය වීරත්වයක් හෝ සාර්ථකත්වයේ සංකේතයක් ලෙස මවා පෙන්වීම", "සෞඛ්‍ය අවවාද පෙන්වීම", "වෛද්‍ය සායන පැවැත්වීම", "මිල ඉහළ දැමීම", "මාධ්‍ය හරහා මවා පෙන්වන ව්‍යාජ ආකර්ෂණය හඳුනාගැනීමට විචාරශීලී චින්තනය අත්‍යවශ්‍ය වේ."),
        q("ශ්‍රී ලංකාවේ බීඩි, සිගරට් සහ දුම්කොළ නිෂ්පාදන පාසල් භූමියක සිට මීටර් කීයක සීමාවක් තුළ විකිණීම නීතියෙන් තහනම් කර තිබේද?", "මීටර් 100ක් ඇතුළත හෝ පාසල් සිසුන්ට අලෙවි කිරීම තහනම්ය", "මීටර් 5ක්", "මීටර් 10ක්", "කිසිදු සීමාවක් නැත", "පාසල් සිසුන් ආරක්ෂා කිරීම සඳහා අධ්‍යාපන ආයතන ආශ්‍රිතව දුම්කොළ හා මත්පැන් අලෙවිය දැඩි ලෙස සීමා කර ඇත."),
        q("මත්ද්‍රව්‍ය භාවිතය නිසා පවුලක් තුළ ඇතිවන ප්‍රධාන සමාජීය හා ආර්ථික ගැටලුව කුමක්ද?", "ආදායම නාස්ති වී දරිද්‍රතාවය ඇතිවීම, ගෘහස්ථ හිංසනය සහ පවුල් සබඳතා බිඳ වැටීම", "පවුලේ සමගිය වැඩිවීම", "දරුවන්ගේ අධ්‍යාපනය දියුණු වීම", "ඉතිරිකිරීම් ඉහළ යාම", "මත්ද්‍රව්‍ය පුද්ගලයාගේ සෞඛ්‍යය මෙන්ම මුළු පවුලේම ආර්ථිකය හා සමාජ ගෞරවය විනාශ කරයි."),
        q("එන්නත් කටු හරහා හෙරොයින් වැනි මත්ද්‍රව්‍ය ශරීරගත කර ගැනීමේදී ඇතිවන අතිරේක මාරාන්තික සෞඛ්‍ය අවදානම කුමක්ද?", "HIV, හෙපටයිටිස් B සහ හෙපටයිටිස් C වැනි රුධිරගත රෝග පැතිරීම", "උණ සන්නිපාතය වැළඳීම", "විටමින් අධික වීම", "රුධිර පට්ටිකා වැඩිවීම", "එකම එන්නත් කටුව හවුලේ භාවිත කිරීම නිසා රුධිරය මගින් බෝවන මාරාන්තික වෛරස් සීඝ්‍රයෙන් පැතිරේ."),
        q("මත්පැන් නිසා මාංශ පේශි සංවර්ධනය වන බව හෝ ශීතල නැතිවන බවට ඇති මතය පිළිබඳ විද්‍යාත්මක සත්‍යය කුමක්ද?", "එය මිථ්‍යාවක් වන අතර මත්පැන් මගින් සමේ රුධිර නාල ප්‍රසාරණය කර ශරීරයේ අභ්‍යන්තර උෂ්ණත්වය තවත් පහත හෙළයි", "එය 100%ක්ම සත්‍යයකි", "මත්පැන් ප්‍රෝටීන් බහුල පානයකි", "මත්පැන් ශරීරයට අත්‍යවශ්‍ය වේ", "මත්පැන් බිව් විට සම උණුසුම් වූ බවක් දැනුණද සිරුරේ අභ්‍යන්තර තාපය වේගයෙන් ඉවතට පිටවී යයි."),
        q("ශාරීරික ආබාධයක් හෝ මානසික ගැටලුවක් නිසා කෙනෙකු කෙරෙහි අනුකම්පාවෙන් බලනවාට වඩා ගෞරවයෙන් සැලකීමට අවශ්‍ය ගුණාංගය කුමක්ද?", "ගරුත්වය හා සමානාත්මතාවයෙන් යුතුව සහකම්පනය දැක්වීම", "අවමන් කිරීම", "කොන් කිරීම", "විහිළුවට ලක් කිරීම", "සෑම මිනිසෙකුගේම ගරුත්වය රැකෙන පරිදි උපකාර කිරීම ශිෂ්ටසම්පන්න සමාජයක ලක්ෂණයකි."),
        q("ක්‍රීඩා තරගයකදී පරාජයට පත් වූ විට ක්‍රීඩකයෙකු තුළ තිබිය යුතු මානසික සමබරතාව කුමක්ද?", "තම අඩුපාඩු විචාරශීලීව හඳුනාගෙන ඊළඟ තරගයට පුහුණුවීම් වැඩි දියුණු කර ගැනීම", "විනිසුරුවන්ට පහර දීම", "ක්‍රීඩාව සදහටම අත්හැරීම", "කණ්ඩායමේ සගයන්ට බැණ වැදීම", "පරාජය යනු ඉගෙනීමේ පියගැටපෙළක් ලෙස සලකා ධනාත්මකව භාරගැනීම උසස් ක්‍රීඩා මානසිකත්වයයි."),
        q("තමන්ගේ ඉලක්ක සපුරා ගැනීම සඳහා තමා තුළම ඇතිවන අභ්‍යන්තර පෙළඹවීම හඳුන්වන්නේ කෙසේද?", "අභ්‍යන්තර අභිප්‍රේරණය (Intrinsic Motivation)", "බාහිර බලපෑම", "බියගුලුකම", "කම්මැලිකම", "බාහිර තෑගි බලාපොරොත්තුවෙන් තොරව තම ආත්ම තෘප්තිය උදෙසා කැපවීම අභ්‍යන්තර අභිප්‍රේරණයයි."),
        q("මානසික සෞඛ්‍යය රැකගැනීම සඳහා 'කෘතවේදීත්වය' (Gratitude) පුරුදු පුහුණු කිරීම වැදගත් වන්නේ කෙසේද?", "තමාට ලැබී ඇති දේවල් අගය කිරීමෙන් සිතේ සතුට, තෘප්තිය සහ ධනාත්මක හැඟීම් වර්ධනය වන බැවින්", "අනෙක් අයට ඊර්ෂ්‍යා කිරීමට", "ධනය අඩු වීමට", "කම්මැලි වීමට", "දිනපතා තමා ලැබූ යහපත් දේ පිළිබඳව ස්තුතිවන්ත වීම මොළයේ සතුට ගෙනෙන රසායනික වර්ධනය කරයි."),
        q("කෙනෙකුගේ කෝපය ක්ෂණිකව පාලනය කර ගැනීමට (Anger Management) යොදාගත හැකි ප්‍රායෝගික ක්‍රමයක් කුමක්ද?", "ප්‍රතිචාර දැක්වීමට පෙර සෙමෙන් 1 සිට 10 දක්වා ගණන් කර ගැඹුරු හුස්මක් ගැනීම", "අතට අසුවන දෙයක් විසි කිරීම", "උස් හඬින් කෑගැසීම", "අන් අයට රිදවීම", "කෙටි විරාමයක් ගැනීම මගින් තර්කානුකූල මොළයට නැවත පාලනය ලබාගැනීමට කාලය ලැබේ."),
        q("මානසික ආතතිය මගහරවා ගැනීම සඳහා විවේක කාලයේදී නිරත විය හැකි නිර්මාණශීලී විනෝදාංශයකට උදාහරණයක් කුමක්ද?", "ගෙවතු වගාව, චිත්‍ර ඇඳීම, සංගීතයට සවන් දීම හෝ පොත් කියවීම", "සූදු කෙළීම", "දුම්පානය කිරීම", "අනුන්ගේ ඕපාදූප සෙවීම", "නිර්මාණශීලී හා ප්‍රබෝධමත් විනෝදාංශ මනස සැහැල්ලු කර ස්වයං තෘප්තිය ලබාදෙයි."),
        q("පුද්ගලයෙකු මත්ද්‍රව්‍යවලට මුලින්ම යොමුවීමට බහුලව බලපාන සමාජීය සාධකයක් වන්නේ කුමක්ද?", "නොගැලපෙන මිතුරු ඇසුර සහ කුතුහලය නිසා අත්හදා බැලීමට යාම", "හොඳ අධ්‍යාපනයක් ලැබීම", "ක්‍රීඩාවලට යොමු වීම", "පවුලේ ආදරය ලැබීම", "'එක පාරක් බීලා බලමු' යන කුතුහලය හා මිතුරු බලපෑම බොහෝ ඇබ්බැහිවීම්වල ආරම්භයයි."),
        q("මත්පැන් හා දුම්වැටි භාවිතයෙන් සම්පූර්ණයෙන් තොර පරිසරයක් නිවස තුළ ගොඩනැගීමට දෙමාපියන් කළ යුත්තේ කුමක්ද?", "දරුවන් ඉදිරියේ මත්පැන් හෝ දුම්වැටි භාවිත නොකර යහපත් ආදර්ශයක් ලබාදීම", "දරුවන්ට සිගරට් මිලදී ගැනීමට කඩයට යැවීම", "උත්සවවලදී මත්පැන් අනිවාර්ය කිරීම", "ඒ පිළිබඳ කතා නොකිරීම", "දෙමාපියන්ගේ ආදර්ශය දරුවන්ගේ හැසිරීම හැඩගැස්වීමේ ප්‍රබලතම සාධකය වේ."),
        q("පාසලක මත්ද්‍රව්‍ය නිවාරණ කමිටුවක් හෝ සෞඛ්‍ය ප්‍රවර්ධන සමාජයක් පිහිටුවීමේ ප්‍රධාන අරමුණ කුමක්ද?", "සිසුන් තුළ මත්ද්‍රව්‍යවලට එරෙහි ආකල්ප ගොඩනගා ආරක්ෂිත පාසල් පරිසරයක් තහවුරු කිරීම", "විභාග ප්‍රතිඵල අඩු කිරීම", "සිසුන්ට දඬුවම් කිරීම පමණි", "බාහිර පුද්ගලයන්ට විවෘත කිරීම", "සිසුන්ගේ සහභාගීත්වයෙන් ක්‍රියාත්මක වන නිවාරණ වැඩසටහන් ඉතා සාර්ථක ප්‍රතිඵල ගෙනදෙයි."),
        q("විභාගයකින් බලාපොරොත්තු වූ ප්‍රතිඵල නොලැබුණු විට සිසුවෙකු සිතිය යුතු නිවැරදි ආකාරය කුමක්ද?", "මෙය ජීවිතයේ අවසානය නොවන බවත්, වැරදුණු තැන් හදාගෙන නැවත උත්සාහ කළ හැකි බවත් සිතීම", "තමා සම්පූර්ණයෙන්ම අසාර්ථක බව සිතීම", "ජීවිතය නැති කර ගැනීමට සිතීම", "අධ්‍යාපනය සදහටම නතර කිරීම", "සෑම අසමත්වීමක්ම නව ආරම්භයක් හා විකල්ප සාර්ථක මාර්ගයකට පිවිසුමක් ලෙස දැකිය යුතුය."),
        q("පුද්ගලයෙකුගේ ස්වයං විශ්වාසය (Self-confidence) වර්ධනය කර ගැනීමට උපකාරී වන හොඳම ක්‍රමය කුමක්ද?", "කුඩා ඉලක්ක තබා ඒවා සාර්ථකව සම්පූර්ණ කිරීම සහ තම හැකියාවන් පුහුණු කිරීම", "අන් අය සමග තමා නිතර සංසන්දනය කර දුක් වීම", "කිසිදු අභියෝගයක් භාර නොගැනීම", "නිතර බියෙන් සැඟවීම", "කුඩා ජයග්‍රහණ ලබා ගන්නා විට තමා පිළිබඳ විශ්වාසය ස්වභාවිකවම ශක්තිමත් වේ."),
        q("සමාජය තුළ යහපත් පුරවැසියෙකු ලෙස ජීවත් වීමට කායික සෞඛ්‍යය මෙන්ම මානසික සුවතාවද සමානව වැදගත් වන්නේ මන්ද?", "සෞඛ්‍ය සම්පන්න ශරීරයක් සහ ප්‍රීතිමත් සංසුන් මනසක් එකට පවතින විට පමණක් පූර්ණ සුවපත් ජීවිතයක් ලැබෙන බැවින්", "මානසික සුවතාව අවශ්‍ය නොවන නිසා", "කායික සෞඛ්‍යය පමණක් ප්‍රමාණවත් නිසා", "රැකියා නොකර සිටීමට", "'නිරෝගී මනසක් නිරෝගී සිරුරක වාසය කරයි' යන සංකල්පය අනුව දෙඅංශයම අත්‍යවශ්‍ය වේ."),
        q("කෙනෙකුට තමාගේ චිත්තවේග හඳුනාගැනීමට සහ අන්‍යයන්ගේ හැඟීම් පාලනය කරමින් සබඳතා පැවැත්වීමට ඇති බුද්ධි හැකියාව කුමක්ද?", "චිත්තවේගීය බුද්ධිය (Emotional Intelligence — EQ)", "බුද්ධි ඵලය (IQ) පමණි", "කායික ශක්තිය", "ගණිතමය හැකියාව", "ජීවිතයේ සාර්ථකත්වය සඳහා IQ මෙන්ම ඉහළ චිත්තවේගීය බුද්ධියක් (EQ) තිබීම ඉතා තීරණාත්මක වේ."),
        q("වැඩිහිටියන්ට සහ ගුරුවරුන්ට ගෞරව කිරීම හා ඔවුන්ගේ අත්දැකීම්වලින් ඉගෙනීම පාසල් ශිෂ්‍යයාගේ සමාජ සංවර්ධනයට වැදගත් වන්නේ ඇයි?", "ප්‍රඥාවන්ත තීරණ ගැනීමට සහ යහපත් සාරධර්ම ජීවිතයට එක් කර ගැනීමට මගපෙන්වීමක් ලැබෙන බැවින්", "ලකුණු වැඩි කර ගැනීමට පමණක්", "බිය නිසා", "වෙනත් විකල්පයක් නැති නිසා", "වැඩිහිටි අත්දැකීම් තරුණ ජවය සමග මුසු වූ විට සාර්ථක හා විනයගරුක ජීවිතයක් ගොඩනැගේ."),
        q("මත්ද්‍රව්‍ය අලෙවිකරුවන් තරුණයන් ආකර්ෂණය කර ගැනීමට සාද හා සංගීත ප්‍රසංගවලදී නොමිලේ ලබාදෙන උගුල කුමක්ද?", "පළමු වරට නොමිලේ මත්ද්‍රව්‍ය අත්හදා බැලීමට දී ඇබ්බැහි කරවා ගැනීම", "පොත් බෙදා හැරීම", "ක්‍රීඩා භාණ්ඩ දීම", "ජල බෝතල් ලබාදීම", "ආරම්භයේදී නොමිලේ දෙන රසායනික පෙති හෝ මත්ද්‍රව්‍යවලට ඇබ්බැහි වූ පසු ජීවිත කාලයම ගොදුරක් බවට පත්කර ගනී."),
        q("සෞඛ්‍ය සම්පන්න පුද්ගලයෙකුට අන් අයගේ විවේචන හමුවේ මානසිකව බිඳ නොවැටී සිටීමට හැකිවන්නේ කුමන ගුණාංගය නිසාද?", "ධනාත්මක ආත්ම අභිමානය සහ ස්වයං අවබෝධය", "අධික කෝපය", "පළිගැනීමේ චේතනාව", "අහංකාරය", "තමා කවුදැයි හඳුනාගත් පුද්ගලයා සාධාරණ විවේචනවලින් ඉගෙන ගන්නා අතර අසාධාරණ විවේචන උපේක්ෂාවෙන් බැහැර කරයි."),
        q("නව යොවුන් වියේ දරුවෙකු තුළ දිගින් දිගටම නිහඬ වීම, පාසල් වැඩ අතපසු කිරීම සහ කේන්ති යාම දක්නට ලැබේ නම් කළ යුත්තේ කුමක්ද?", "ආදරයෙන් හා විවෘතව ඔහුට සවන් දී ගැටලුව විමසා අවශ්‍ය නම් උපදේශන සහය ලබාදීම", "දැඩිව දඬුවම් කිරීම", "නොසලකා හැරීම", "පාසලෙන් ඉවත් කිරීම", "හැසිරීමේ හදිසි වෙනස්කම් මානසික පීඩනයක හෝ ගැටලුවක සලකුණක් විය හැකි බැවින් කරුණාවෙන් සොයා බැලිය යුතුය."),
        q("සිසුන් තුළ සාමූහිකත්වය, නායකත්වය සහ විනය වර්ධනය කිරීමට පාසල තුළ ක්‍රියාත්මක කළ හැකි හොඳම බාහිර ක්‍රියාකාරකම කුමක්ද?", "කණ්ඩායම් ක්‍රීඩා, ශිෂ්‍ය භට, බාලදක්ෂ හා ශිෂ්‍ය සමාජවල ක්‍රියාකාරී වීම", "තනිව පරිගණක ක්‍රීඩා කිරීම", "නිවසට වී සිටීම", "රූපවාහිනී නැරඹීම", "සාමූහික ක්‍රියාකාරකම් තුළින් ඉවසීම, වගකීම හා නායකත්ව ගුණාංග ප්‍රායෝගිකව ප්‍රගුණ වේ."),
        q("නිරෝගී මානසික සුවතාවයක් ගොඩනගා ගැනීමේ අවසාන ප්‍රතිලාභය කුමක්ද?", "තමාටත් අන් අයටත් ප්‍රයෝජනවත් සතුටුදායක, සමබර සහ අර්ථවත් ජීවිතයක් ගත කිරීමට හැකිවීම", "තනිව ජීවත් වීම", "ධනය පමණක් රැස් කිරීම", "ප්‍රසිද්ධ වීම පමණක්", "මානසික සුවතාව පුද්ගලයාගේ සැබෑ සතුට, සාර්ථකත්වය සහ සමාජ යහපතේ පදනමයි.")
    )
}
